#!/usr/bin/env bash
# ============================================================================
# FIRONOVA - Installeur programme d'affiliation (BACKEND) - IDEMPOTENT
# Gere installation fraiche ET mise a jour, sans doublon. Backup + AST.
# A executer depuis /app :   bash install_affiliates_backend.sh
# ============================================================================
set -euo pipefail
cd "$(dirname "$0")"
SERVER="backend/server.py"; [ -f "$SERVER" ] || SERVER="server.py"
[ -f "$SERVER" ] || { echo "server.py introuvable"; exit 1; }
cp "$SERVER" "${SERVER}.bak-aff-$(date +%Y%m%d-%H%M%S)"
echo "Backup cree."

export AFF_B64=''

python3 - "$SERVER" << 'PYEOF'
import sys, os, re, base64, ast
path = sys.argv[1]
raw = open(path).read()
START = "# ===== FIRONOVA_AFFILIATE_BLOCK_START ====="
END = "# ===== FIRONOVA_AFFILIATE_BLOCK_END ====="

had_block = (START in raw and END in raw)
src = re.sub(re.escape(START)+r".*?"+re.escape(END), "<<<AFF_BLOCK>>>", raw, count=1, flags=re.DOTALL) if had_block else raw

def patch(src, anchor, insert, sentinel, label):
        """sentinel = ligne d'action unique qui prouve que le patch est deja la
        (robuste aux differences de commentaire entre versions)."""
        if sentinel in src:
                print(f"  [{label}] deja present"); return src
        n = src.count(anchor)
        if n != 1:
                raise SystemExit(f"[{label}] ancre {n}x (attendu 1) - abandon.")
        print(f"  [{label}] applique"); return src.replace(anchor, insert)

# P1
a1='    await db.orders.insert_one(order_doc)\n    order_doc.pop("_id", None)'
i1='    await affiliate_attach_to_order(order_doc, request)\n'+a1
src=patch(src,a1,i1,"await affiliate_attach_to_order(order_doc, request)","patch1-checkout")

# P2
a2='    # asyncio.create_task(_auto_create_dispatch_label(order_id))\n    return order'
i2='    # asyncio.create_task(_auto_create_dispatch_label(order_id))\n    await affiliate_on_order_paid(order)\n    return order'
src=patch(src,a2,i2,"await affiliate_on_order_paid(order)","patch2-markpaid")

# P3 (prorata) - gere 3 etats : absent / ancien(full) / a jour
i3=('    await db.orders.update_one({"id": order_id}, {"$set": update, "$push": {"notes": note}})\n'
        '    await affiliate_on_order_refunded(order_id, new_refunded, total)\n'
        '    updated = await db.orders.find_one({"id": order_id}, {"_id": 0})\n'
        '    if updated.get("email"):\n'
        '        asyncio.create_task(send_refund_email(updated, amount, new_refunded))')
a3o=('    await db.orders.update_one({"id": order_id}, {"$set": update, "$push": {"notes": note}})\n'
         '    updated = await db.orders.find_one({"id": order_id}, {"_id": 0})\n'
         '    if updated.get("email"):\n'
         '        asyncio.create_task(send_refund_email(updated, amount, new_refunded))')
if "await affiliate_on_order_refunded(order_id, new_refunded, total)" in src:
        print("  [patch3-refund] deja present")
else:
        # retire d'abord un eventuel ancien bloc full=True
        a3prev=('    # --- AFFILIATE: annule la commission si remboursement total ---\n'
                        '    if new_refunded >= total:\n'
                        '        await affiliate_on_order_reversed(order_id, full=True)\n')
        if a3prev in src:
                src=src.replace(a3prev,''); print("  [patch3-refund] ancien bloc full retire")
        src=patch(src,a3o,i3,"await affiliate_on_order_refunded(order_id, new_refunded, total)","patch3-refund")

# P4
a4='    await db.products.create_index("slug", unique=True)'
i4=a4+'\n    await affiliate_ensure_indexes()'
src=patch(src,a4,i4,"await affiliate_ensure_indexes()","patch4-indexes")

# P5
a5='        asyncio.create_task(_magic_tokens_cleanup())'
i5=a5+'\n        asyncio.create_task(affiliate_maintenance_watchdog())'
src=patch(src,a5,i5,"asyncio.create_task(affiliate_maintenance_watchdog())","patch5-startup")

# Bloc
BLOCK=base64.b64decode(os.environ["AFF_B64"]).decode()
wrapped=START+"\n"+BLOCK+"\n"+END
if had_block:
        src=src.replace("<<<AFF_BLOCK>>>",wrapped,1); print("  [bloc] remplace")
else:
        m="app.include_router(api)"
        if src.count(m)!=1: raise SystemExit("include_router introuvable - abandon.")
        src=src.replace(m,wrapped+"\n\n"+m); print("  [bloc] injecte")

ast.parse(src); open(path,"w").write(src)
print("OK - server.py a jour, AST valide.")
PYEOF
echo "Termine. Redemarre le backend."
